typedef float rational_t;
typedef float fp;

extern "C" float sqrtf(float);

const rational_t SMALL_DIST = 0.00001f;

inline fp fast_recip_sqrt(fp x)
{
  return 1.0F/(rational_t)sqrtf(x);
}

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }

  inline T length2() const
  { return x*x + y*y + z*z; }

  inline vector3d& operator *= (T d)
  { x *= d; y *= d; z *= d; return *this; }

  inline vector3d& normalize()
  {
    T l2 = length2();
    if (l2>SMALL_DIST*SMALL_DIST)
      *this *= fast_recip_sqrt(l2);
    return *this;
  }
};

inline rational_t dot(const vector3d& a, const vector3d& b)
{ return a.x*b.x + a.y*b.y + a.z*b.z; }

template <class spacial_t>
class hyperplane
{
protected:
  rational_t d;
  spacial_t normal;
public:
  hyperplane(const spacial_t& c,const spacial_t& n)
    : normal(n)
  {
    normal.normalize();
    d = dot(normal,c);
  }
};

class sector;

class partition3 : public hyperplane<vector3d>
{
public:
  typedef hyperplane<vector3d> _H;
private:
  sector* my_sector;
public:
  partition3(const vector3d& c, const vector3d& n, sector* s);
};

partition3::partition3(const vector3d& c, const vector3d& n, sector* s)
  : _H(c, n),
    my_sector(s)
{
}
